"use strict";(self.webpackChunk_313_k8sai_site=self.webpackChunk_313_k8sai_site||[]).push([["8210"],{5505(e,t,s){s.r(t),s.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>r,contentTitle:()=>i,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"m2-ai-infrastructure-primer/deep-dive","title":"Deep Dive \u2014 KV Cache, Paged Blocks, the Decode Bound and Ring All-Reduce Cost","description":"The lab gave you a budget for memory, a capacity from demand and a cost. Each rested on a formula that the calculators applied for you. This page opens the four formulas underneath: why the cache is as large as it is, how an engine wastes less of it, how fast one request can possibly be answered, and what the network costs a training step. You will use these when a team asks \\"why does this model run out of memory at twenty users\\", \\"why is it slow even with nobody else on it\\" and \\"why did adding servers not speed up training\\". All four are arithmetic, so every figure here is an estimate from stated inputs.","source":"@site/docs/m2-ai-infrastructure-primer/deep-dive.md","sourceDirName":"m2-ai-infrastructure-primer","slug":"/m2-ai-infrastructure-primer/deep-dive","permalink":"/313-k8sai-site/m2-ai-infrastructure-primer/deep-dive","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"id":"deep-dive","sidebar_position":4,"title":"Deep Dive \u2014 KV Cache, Paged Blocks, the Decode Bound and Ring All-Reduce Cost","sidebar_label":"Deep Dive (Part 2)"},"sidebar":"courseSidebar","previous":{"title":"Lab","permalink":"/313-k8sai-site/m2-ai-infrastructure-primer/lab"},"next":{"title":"Knowledge check","permalink":"/313-k8sai-site/m2-ai-infrastructure-primer/quiz"}}'),a=s(4848),o=s(8453);let r={id:"deep-dive",sidebar_position:4,title:"Deep Dive \u2014 KV Cache, Paged Blocks, the Decode Bound and Ring All-Reduce Cost",sidebar_label:"Deep Dive (Part 2)"},i="Deep Dive \u2014 KV Cache, Paged Blocks, the Decode Bound and Ring All-Reduce Cost",d={},h=[{value:"1 \u2014 Why the KV cache is as large as it is",id:"1--why-the-kv-cache-is-as-large-as-it-is",level:2},{value:"2 \u2014 Paged blocks and internal fragmentation",id:"2--paged-blocks-and-internal-fragmentation",level:2},{value:"3 \u2014 The bandwidth-bound decode upper bound",id:"3--the-bandwidth-bound-decode-upper-bound",level:2},{value:"4 \u2014 The cost model of ring all-reduce",id:"4--the-cost-model-of-ring-all-reduce",level:2},{value:"Teardown",id:"teardown",level:2},{value:"Where you will use this",id:"where-you-will-use-this",level:2}];function l(e){let t={admonition:"admonition",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"deep-dive--kv-cache-paged-blocks-the-decode-bound-and-ring-all-reduce-cost",children:"Deep Dive \u2014 KV Cache, Paged Blocks, the Decode Bound and Ring All-Reduce Cost"})}),"\n",(0,a.jsx)(t.p,{children:'The lab gave you a budget for memory, a capacity from demand and a cost. Each rested on a formula that the calculators applied for you. This page opens the four formulas underneath: why the cache is as large as it is, how an engine wastes less of it, how fast one request can possibly be answered, and what the network costs a training step. You will use these when a team asks "why does this model run out of memory at twenty users", "why is it slow even with nobody else on it" and "why did adding servers not speed up training". All four are arithmetic, so every figure here is an estimate from stated inputs.'}),"\n",(0,a.jsxs)(t.admonition,{title:"Where this picks up",type:"info",children:[(0,a.jsxs)(t.p,{children:["This page needs only your clone and the ",(0,a.jsx)(t.code,{children:"m2"})," folder from the lab. No cluster is involved. It writes scratch files under ",(0,a.jsx)(t.code,{children:"/tmp/m2-dd"})," and never changes your inputs, so re-running any block is safe. Run everything from the root of your clone."]}),(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"mkdir -p /tmp/m2-dd && ls m2/kv-blocks.sh m2/decode-bound.sh m2/allreduce.sh\n"})}),(0,a.jsx)(t.p,{children:"[ Expected output ]"}),(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"m2/allreduce.sh\nm2/decode-bound.sh\nm2/kv-blocks.sh\n"})})]}),"\n",(0,a.jsx)(t.h2,{id:"1--why-the-kv-cache-is-as-large-as-it-is",children:"1 \u2014 Why the KV cache is as large as it is"}),"\n",(0,a.jsxs)(t.p,{children:["A model reads a prompt word by word, and every new word is compared with all the words before it. To avoid redoing that work, the server stores two small tables for every earlier word, a ",(0,a.jsx)(t.strong,{children:"key"})," and a ",(0,a.jsx)(t.strong,{children:"value"}),". That store is the KV cache. Now think of a library reading room. Every reader at the table (a query head) wants to consult notes. In the old design each reader had a private notebook. In ",(0,a.jsx)(t.strong,{children:"grouped-query attention"})," several readers share one notebook, and in the extreme case, called multi-query attention, the whole table shares one. The readers still read separately. They just stop copying the same notes."]}),"\n",(0,a.jsx)(t.p,{children:"The formula counts notebooks. Each token stores a key and a value (the 2), in every layer, for every key-value head, each of a fixed width, at the bytes per value you chose."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"KV bytes per token = 2 * layers * kv_heads * head_dim * bytes per value\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Here is the proof on one model. The first model file has 28 attention heads and 4 key-value heads, as its published ",(0,a.jsx)(t.code,{children:"config.json"})," states."," Make copies of it with the key-value head count changed to 28 (one notebook per reader), 8, 4 and 1, and run the same scenario."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"for h in 28 8 4 1; do\n  sed \"s/^num_key_value_heads=.*/num_key_value_heads=$h/\" m2/inputs/models/qwen2.5-7b-instruct.conf > /tmp/m2-dd/kv$h.conf\n  echo \"kv_heads=$h $(bash m2/vram-budget.sh /tmp/m2-dd/kv$h.conf m2/inputs/vram-scenario.conf | grep -E '^(kv_bytes_per_token|kv_gb_all_requests)=' | tr '\\n' ' ')\"\ndone\n"})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"kv_heads=28 kv_bytes_per_token=401408 kv_gb_all_requests=52.61 \nkv_heads=8 kv_bytes_per_token=114688 kv_gb_all_requests=15.03 \nkv_heads=4 kv_bytes_per_token=57344 kv_gb_all_requests=7.52 \nkv_heads=1 kv_bytes_per_token=14336 kv_gb_all_requests=1.88 \n"})}),"\n",(0,a.jsx)(t.p,{children:"The cache per token is linear in the head count. The 28-head copy is seven times the real model, and that ratio is the whole saving of grouped-query attention. The cache for all requests also grows linearly with context and with concurrency, so the three levers multiply. A product team that doubles the context and doubles the concurrent users has asked for four times the cache, and the weights did not change at all."}),"\n",(0,a.jsx)(t.p,{children:"The cost is not abstract. When the weights already take most of a card, the cache is what is left, and the number of requests one replica can hold is that remainder divided by the cache per request. Part 2 of the lab used this to find the replicas that memory demands. Two models of about the same parameter count can differ by more than a factor of two in cache per token, as the lab's Mistral and Qwen files did, and only the model card tells you."}),"\n",(0,a.jsx)(t.h2,{id:"2--paged-blocks-and-internal-fragmentation",children:"2 \u2014 Paged blocks and internal fragmentation"}),"\n",(0,a.jsxs)(t.p,{children:["Think of a hotel that books by the room. A group of five guests takes three rooms and leaves a spare bed, and the hotel can give every other room to someone else. The alternative is to book the guest group a whole floor because they might bring more people. The floor is empty most of the time and nobody else can use it. An engine that sets aside the maximum context for every request is booking floors. An engine that hands out small fixed blocks of cache, called ",(0,a.jsx)(t.strong,{children:"paged blocks"}),", as a sequence grows is booking rooms."]}),"\n",(0,a.jsxs)(t.p,{children:["With blocks, a sequence of L tokens needs L divided by the block size, rounded up to a whole number of blocks. The only waste is the unused tail of its last block, called ",(0,a.jsx)(t.strong,{children:"internal fragmentation"}),". The calculator compares that with reserving the whole context for each request. The sample lengths come from your scenario file, and they are declared assumptions."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"bash m2/kv-blocks.sh m2/inputs/models/qwen2.5-7b-instruct.conf m2/inputs/vram-scenario.conf | sed -n '/^RESULTS/,$p'\n"})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"RESULTS (modelled for Qwen2.5-7B-Instruct):\nblock_bytes=917504\ntokens   blocks   tail_waste paged_waste_pct reserved_waste_pct\n700      44       4          0.6            91.5            \n1500     94       4          0.3            81.7            \n3000     188      8          0.3            63.4            \n5000     313      8          0.2            39.0            \n8000     500      0          0.0            2.3             \nmean_blocks_per_request=227.8\npaged_waste_gb_for_all_requests=0.0044\nreserved_waste_gb_for_all_requests=4.1765\npaged_fragmentation_pct=0.13\nreserved_fragmentation_pct=55.57\n"})}),"\n",(0,a.jsx)(t.p,{children:"Read the two waste columns. Paged waste stays small for every length, because a tail is at most one block. Reserved waste depends entirely on how short the real requests are compared with the maximum, so it is large exactly when most requests are short. Now make blocks eight times larger and run it again."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"sed 's/^block_tokens=.*/block_tokens=128/' m2/inputs/vram-scenario.conf > /tmp/m2-dd/blocks128.conf\nbash m2/kv-blocks.sh m2/inputs/models/qwen2.5-7b-instruct.conf /tmp/m2-dd/blocks128.conf | sed -n '/^RESULTS/,$p'\n"})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"RESULTS (modelled for Qwen2.5-7B-Instruct):\nblock_bytes=7340032\ntokens   blocks   tail_waste paged_waste_pct reserved_waste_pct\n700      6        68         8.9            91.5            \n1500     12       36         2.3            81.7            \n3000     24       72         2.3            63.4            \n5000     40       120        2.3            39.0            \n8000     63       64         0.8            2.3             \nmean_blocks_per_request=29.0\npaged_waste_gb_for_all_requests=0.0661\nreserved_waste_gb_for_all_requests=4.1765\npaged_fragmentation_pct=1.94\nreserved_fragmentation_pct=55.57\n"})}),"\n",(0,a.jsx)(t.p,{children:"A larger block wastes a larger tail, and a smaller block means more blocks to track. Engines pick the block size as a trade-off between the two. Two conditions apply to every line above. The five sample lengths are an assumption, not traffic. And the calculator models only the tail. Real engines also share blocks between requests that start with the same prompt, which saves more, and that sharing is the subject of Module 9."}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n  REQ["Request, L tokens"] --\x3e BLK["ceil(L / block size) blocks"]\n  BLK --\x3e TAIL["Unused tail of last block<br/>= internal fragmentation"]\n  BLK --\x3e POOL["Free block pool<br/>(engine allocates on demand)"]\n  RES["Reserve-the-maximum scheme"] --\x3e WASTE["Context minus L, wasted"]'}),"\n",(0,a.jsx)(t.h2,{id:"3--the-bandwidth-bound-decode-upper-bound",children:"3 \u2014 The bandwidth-bound decode upper bound"}),"\n",(0,a.jsxs)(t.p,{children:["Answering a request has two phases. In the first, the server reads the whole prompt in one pass. In the second, called ",(0,a.jsx)(t.strong,{children:"decode"}),", it produces one token at a time. Each new token needs the model to look at every weight. Go back to the kitchen. The cooks are fast, but for every single token they must read the entire recipe book through the pantry door before they cook anything. If the book is fifteen GB and the door passes 3350 GB each second, you can read the book about two hundred and twenty times each second, and you cannot make tokens faster than that however many cooks you add. The 3350 GB each second is the vendor's printed figure for the H100 SXM."]}),"\n",(0,a.jsx)(t.p,{children:"That gives an upper bound for one request on its own:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"tokens per second <= memory bandwidth (GB/s) / weight bytes read per token (GB)\n"})}),"\n",(0,a.jsxs)(t.p,{children:["The conditions are strict, and they are printed in the calculator's header. The batch size is one. The weights are read once per token, with no cache reads. No kernel overhead and no overlap are counted. So the bound is optimistic by construction, and every line ends with ",(0,a.jsx)(t.code,{children:"(estimate)"}),"."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"bash m2/decode-bound.sh m2/inputs/models/qwen2.5-7b-instruct.conf | sed -n '/^RESULTS/,$p'\n"})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"RESULTS (modelled for Qwen2.5-7B-Instruct):\nl4         NVIDIA L4                   300 GB/s /  15.2312 GB =    19.7 tokens/s (estimate)\nl40s       NVIDIA L40S                 864 GB/s /  15.2312 GB =    56.7 tokens/s (estimate)\na100_pcie  NVIDIA A100 80GB PCIe      1935 GB/s /  15.2312 GB =   127.0 tokens/s (estimate)\na100_sxm   NVIDIA A100 80GB SXM       2039 GB/s /  15.2312 GB =   133.9 tokens/s (estimate)\nh100_sxm   NVIDIA H100 SXM            3350 GB/s /  15.2312 GB =   219.9 tokens/s (estimate)\nh100_nvl   NVIDIA H100 NVL            3900 GB/s /  15.2312 GB =   256.1 tokens/s (estimate)\nh200       NVIDIA H200                4800 GB/s /  15.2312 GB =   315.1 tokens/s (estimate)\nmi300x     AMD Instinct MI300X        5300 GB/s /  15.2312 GB =   348.0 tokens/s (estimate)\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Read the bandwidth column. The memory of each card is printed in the calculator's header, which the ",(0,a.jsx)(t.code,{children:"sed"})," cuts off here, and it plays no part in the bound. The H100 SXM line is the vendor's bandwidth divided by the weights in this scenario. Cards with more memory are not automatically faster here, and the ranking follows bandwidth. The weights are printed to four decimal places so that you can divide the two printed figures yourself and get the printed bound. Now run the 72B model, whose figures come from its own ",(0,a.jsx)(t.code,{children:"config.json"})," at a pinned revision."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"bash m2/decode-bound.sh m2/inputs/models/qwen2.5-72b-instruct.conf | sed -n '/^RESULTS/,$p'\n"})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"RESULTS (modelled for Qwen2.5-72B-Instruct):\nl4         NVIDIA L4                   300 GB/s / 145.4124 GB =     2.1 tokens/s [weights exceed one card] (estimate)\nl40s       NVIDIA L40S                 864 GB/s / 145.4124 GB =     5.9 tokens/s [weights exceed one card] (estimate)\na100_pcie  NVIDIA A100 80GB PCIe      1935 GB/s / 145.4124 GB =    13.3 tokens/s [weights exceed one card] (estimate)\na100_sxm   NVIDIA A100 80GB SXM       2039 GB/s / 145.4124 GB =    14.0 tokens/s [weights exceed one card] (estimate)\nh100_sxm   NVIDIA H100 SXM            3350 GB/s / 145.4124 GB =    23.0 tokens/s [weights exceed one card] (estimate)\nh100_nvl   NVIDIA H100 NVL            3900 GB/s / 145.4124 GB =    26.8 tokens/s [weights exceed one card] (estimate)\nh200       NVIDIA H200                4800 GB/s / 145.4124 GB =    33.0 tokens/s [weights exceed one card] (estimate)\nmi300x     AMD Instinct MI300X        5300 GB/s / 145.4124 GB =    36.4 tokens/s (estimate)\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Lines marked ",(0,a.jsx)(t.code,{children:"[weights exceed one card]"})," are shown only so you can see the arithmetic. On those cards the weights alone are larger than the memory the vendor prints for one card, before any cache, so the number describes no real deployment on one card. Two more cautions. For a mixture-of-experts model such as Mixtral, a token reads only the experts it uses, so dividing by the total weights would give a pessimistic figure, not an upper bound. This course does not state the active parameter count for it, because the model card does not. And batching changes the picture: reading the weights once serves every request in the batch, which is why engines batch, and why the per-request bound and the fleet's total throughput are different numbers."]}),"\n",(0,a.jsx)(t.h2,{id:"4--the-cost-model-of-ring-all-reduce",children:"4 \u2014 The cost model of ring all-reduce"}),"\n",(0,a.jsxs)(t.p,{children:["Training makes every card hold the same correction at the end of a step. Imagine a ring of cooks, each holding a pot of the same size. Each cook splits the pot into as many portions as there are cooks, and passes one portion to the neighbour while receiving one from the other side. After enough passes everybody has the combined pot. This is the ",(0,a.jsx)(t.strong,{children:"ring all-reduce"}),". Each card sends and receives the data twice over in total, in small chunks, and the passing happens at the same time around the ring."]}),"\n",(0,a.jsx)(t.p,{children:"With N cards and S gigabytes of data per card, each card moves about 2(N-1)/N times S. Divide by the bandwidth B of the link each card sends over, and you have the time of the bandwidth term:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"time = 2 * (N - 1) / N * S / B\n"})}),"\n",(0,a.jsx)(t.p,{children:"The factor 2(N-1)/N is below two for any N and approaches two as N grows. That is the useful surprise. Beyond a handful of cards, adding more does not make the ring much slower, and it does not make it faster either. The time is set by S over B, the size of the data and the speed of the slowest link. Run the calculator on your link classes, which are declared round numbers, not vendor specifications."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"bash m2/allreduce.sh m2/inputs/interconnect.conf | sed -n '/^RESULTS/,$p'\n"})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"RESULTS (modelled):\nin_node_fast in-node fast link class      B= 450.0 GB/s time_s=0.0583 (estimate)\nin_node_pcie in-node PCIe class           B=  50.0 GB/s time_s=0.5250 (estimate)\nnet_400g     network 400 Gbit/s class     B=  50.0 GB/s time_s=0.5250 (estimate)\nnet_100g     network 100 Gbit/s class     B=  12.5 GB/s time_s=2.1000 (estimate)\n"})}),"\n",(0,a.jsx)(t.p,{children:"Now vary the number of cards and keep the links. Copy the file with two, eight and sixty-four participants, and print only the slowest and the fastest link."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:'for n in 2 8 64; do\n  sed "s/^participants=.*/participants=$n/" m2/inputs/interconnect.conf > /tmp/m2-dd/ring$n.conf\n  echo "participants=$n"\n  bash m2/allreduce.sh /tmp/m2-dd/ring$n.conf | grep -E \'^(in_node_fast|net_100g) \'\ndone\n'})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"participants=2\nin_node_fast in-node fast link class      B= 450.0 GB/s time_s=0.0333 (estimate)\nnet_100g     network 100 Gbit/s class     B=  12.5 GB/s time_s=1.2000 (estimate)\nparticipants=8\nin_node_fast in-node fast link class      B= 450.0 GB/s time_s=0.0583 (estimate)\nnet_100g     network 100 Gbit/s class     B=  12.5 GB/s time_s=2.1000 (estimate)\nparticipants=64\nin_node_fast in-node fast link class      B= 450.0 GB/s time_s=0.0656 (estimate)\nnet_100g     network 100 Gbit/s class     B=  12.5 GB/s time_s=2.3625 (estimate)\n"})}),"\n",(0,a.jsx)(t.p,{children:"From two to eight participants the time for each link rises by three quarters, and from eight to sixty-four by only an eighth, because the factor 2(N-1)/N is already close to two. Between the two links it changes by a factor of thirty-six, the ratio of their bandwidths. A ring that spans servers has to cross the network, so its pace is the network row, even when the links inside each server are many times faster. This is the reason placement matters for training, and the reason Module 6 and Module 7 pay so much attention to the network. Conditions: the formula covers the bandwidth term only. Per-hop latency, overlap with compute and the real topology of the fabric are outside it, and a real training step on real hardware would include all three."}),"\n",(0,a.jsx)(t.h2,{id:"teardown",children:"Teardown"}),"\n",(0,a.jsx)(t.p,{children:"This page changed nothing in your clone."}),"\n",(0,a.jsxs)(t.p,{children:["Remove the scratch files it wrote under ",(0,a.jsx)(t.code,{children:"/tmp/m2-dd"}),". The second line confirms the folder is gone."]}),"\n",(0,a.jsx)(t.p,{children:"Your inputs and your committed documents stay as the lab left them, and nothing else needs undoing, because no cluster was involved."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:'rm -rf /tmp/m2-dd\ntest -e /tmp/m2-dd || echo "/tmp/m2-dd removed"\n'})}),"\n",(0,a.jsx)(t.p,{children:"[ Expected output ]"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"/tmp/m2-dd removed\n"})}),"\n",(0,a.jsx)(t.h2,{id:"where-you-will-use-this",children:"Where you will use this"}),"\n",(0,a.jsx)(t.admonition,{title:"Where you will use this",type:"tip",children:(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"The KV cache per token is two, into layers, into key-value heads, into head width, into bytes per value, and it grows with context and with concurrency together."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," a team asks to double the context window or the user count. Read the model card for the number of key-value heads, rerun the budget and the capacity table, and tell them the cache need before they find it out as an out-of-memory error."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Paged blocks waste at most the tail of one block per request, while reserving the maximum wastes the gap between the maximum and the real length."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," two engines, or two settings, show very different capacity for the same card. Check the block size and how the engine reserves memory before you blame the hardware."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Single-request decode speed is bounded by memory bandwidth divided by the weight bytes read for each token."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," someone asks for a faster accelerator to speed up one slow chat. Compare the bandwidth of the card you have with the bound for your model. If you are already near it, a different card with more bandwidth, a smaller model or batching is the answer, and more cooks are not."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Ring all-reduce time depends on data size over the slowest link, and beyond a handful of cards hardly on how many there are."})," ",(0,a.jsx)(t.strong,{children:"Use it when:"})," a training job is slow only when it spans servers. Find the slowest link on the path and the size of the data it carries, before you add cards or change the job."]}),"\n"]})})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},8453(e,t,s){s.d(t,{R:()=>r,x:()=>i});var n=s(6540);let a={},o=n.createContext(a);function r(e){let t=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),n.createElement(o.Provider,{value:t},e.children)}}}]);